import { Injectable, NestMiddleware } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';

@Injectable()
export class LoggerMiddleware implements NestMiddleware {
  use(req: Request, res: Response, next: NextFunction) {
    console.log(`[${new Date().toISOString()}] Yengi so'rov keldi: ${req.method} ${req.originalUrl}`);

    // Agar ma'lum shart to'g'ri kelmasa shu yerda res.send() bilan javob qaytarib, jarayonni to'xtatish ham mumkin.
    // Lekin hammasi joyida bo'lsa next() chaqirilishi shart! Yo'qsa dastur qotib qoladi.
    next(); 
  }
}

