import { Controller, Get, Injectable, MiddlewareConsumer, Module, NestMiddleware, NestModule } from "@nestjs/common"
import type { NextFunction, Request, Response } from "express"

@Injectable()
class TimingMiddleware implements NestMiddleware {
    use(req: Request, res: Response, next: NextFunction) {
        const start = Date.now()
        res.on("finish", () => {
            const ms = Date.now() - start
            console.log(`  ${req.method} ${req.originalUrl} ${res.statusCode} — ${ms >= 20 ? "≥20" : "<20"}ms`)
        })
        next()
    }
}

