import { Controller, Get, Injectable, MiddlewareConsumer, Module, NestMiddleware, NestModule } from "@nestjs/common"
import type { NextFunction, Request, Response } from "express"

@Injectable()
class BlacklistService {
    private blocked = new Set(["10.0.0.66"])
    isBlocked(ip: string) { return this.blocked.has(ip) }
}

@Injectable()
class IpFilterMiddleware implements NestMiddleware {
    constructor(private readonly blacklist: BlacklistService) {}      // oddiy servis kabi inject
    use(req: Request, res: Response, next: NextFunction) {
        const ip = (req.headers["x-forwarded-for"] as string) ?? "127.0.0.1"
        if (this.blacklist.isBlocked(ip)) {
            res.status(403).send("IP bloklangan")
            return
        }
        next()
    }
}

@Controller() class HomeController { @Get() home() { return "xush kelibsiz" } }

@Module({ controllers: [HomeController], providers: [BlacklistService] })
class AppModule implements NestModule {
    configure(consumer: MiddlewareConsumer) {
        consumer.apply(IpFilterMiddleware).forRoutes("*")
    }
}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/")
    await http.get("/", { "X-Forwarded-For": "10.0.0.66" })
    await http.close()
}
main()

import { Controller, Get, Injectable, MiddlewareConsumer, Module, NestMiddleware, NestModule } from "@nestjs/common"

@Injectable()
class SimpleCorsMiddleware implements NestMiddleware {
    use(req: any, res: any, next: () => void) {
