import { Controller, Get, Injectable, MiddlewareConsumer, Module, NestMiddleware, NestModule, Req } from "@nestjs/common"

@Injectable()
class TenantMiddleware implements NestMiddleware {
    private tenants: Record<string, { name: string; plan: string }> = { t1: { name: "Korzinka", plan: "pro" } }
    async use(req: any, res: any, next: () => void) {
        await new Promise(r => setTimeout(r, 10)) // "baza"
        const tenant = this.tenants[req.headers["x-tenant"]]
        if (!tenant) { res.statusCode = 400; return res.end(JSON.stringify({ message: "Tenant noma'lum" })) }
        req.tenant = tenant
        next()
    }
}

