import { Controller, Get, Injectable, MiddlewareConsumer, Module, NestMiddleware, NestModule } from "@nestjs/common"
import type { NextFunction, Request, Response } from "express"

const cache = new Map<string, string>()
@Injectable() class MicroCache implements NestMiddleware {
    use(req: Request, res: Response, n: NextFunction) {
        const hit = cache.get(req.originalUrl)
        if (hit) { res.setHeader("X-Cache", "HIT"); res.type("json").send(hit); return }
        const orig = res.send.bind(res)
        res.send = ((body: unknown) => { cache.set(req.originalUrl, String(body)); res.setHeader("X-Cache", "MISS"); return orig(body) }) as typeof res.send
        n()
    }
}
