import { Controller, Get, MiddlewareConsumer, Module, NestModule } from "@nestjs/common"

const MAINTENANCE = true

function maintenance(req: any, res: any, next: () => void) {
    if (MAINTENANCE && req.originalUrl !== "/health") {
        res.statusCode = 503
        res.setHeader("Retry-After", "600")
        res.setHeader("Content-Type", "application/json")
        return res.end(JSON.stringify({ message: "Texnik ishlar. 10 daqiqadan so'ng qaytib keling." }))
    }
    next()
}

