import { Controller, Get, Module } from "@nestjs/common"
import type { NextFunction, Request, Response } from "express"

function rateLimit(max: number, windowMs: number) {
    const hits = new Map<string, { count: number; reset: number }>()
    return (req: Request, res: Response, next: NextFunction) => {
        const key = req.ip ?? "?"
        const now = Date.now()
        const h = hits.get(key)?.reset! > now ? hits.get(key)! : { count: 0, reset: now + windowMs }
        h.count++
        hits.set(key, h)
        res.setHeader("X-RateLimit-Remaining", String(Math.max(0, max - h.count)))
        if (h.count > max) { res.status(429).json({ message: "Juda ko'p so'rov" }); return }
        next()
    }
}

