const used = new Set<string>()
const idempotency = (req: Request, res: Response, n: NextFunction) => {
    const key = req.headers["idempotency-key"]
    if (req.method !== "POST" || typeof key !== "string") return n()
    if (used.has(key)) { res.status(409).json({ xato: "Bu so'rov allaqachon bajarilgan" }); return }
    used.add(key); n()
}
