import { Module, NestModule, MiddlewareConsumer, RequestMethod } from '@nestjs/common';
import { LoggerMiddleware } from './logger.middleware';
import { logger } from './functional-logger.middleware';

@Module({
  imports: [],
})
export class AppModule implements NestModule {

  // NestModule interfeysidan keladigan majburiy metod
  configure(consumer: MiddlewareConsumer) {
    consumer
      // 1. Class middleware ni barcha 'cats' URL lari uchun ulash
      .apply(LoggerMiddleware)
      .forRoutes('cats'); 

    consumer
      // 2. Functional middleware ni faqat POST metodidagi 'users' ga ulash
      .apply(logger)
      .forRoutes({ path: 'users', method: RequestMethod.POST });
  }
}

