@Controller("b") class B { @Get() b() { return "" } }
@Module({ controllers: [B] }) class AppModule {}

async function main() {
    const mw = new Brand()
    const http = await testApp(AppModule, app => app.use(mw.use.bind(mw)))
    const r = await http.get("/b")
    console.log(r.headers.get("x-brand"), "(DI'siz — faqat oddiy middleware uchun)")
    await http.close()
}
main()
